import {useRoutePayload} from '@github-ui/react-core/use-route-payload'
import {Flash, Heading} from '@primer/react'
import type {IndexRoutePayload} from './types'
import {SinkList} from '../../components/SinkList'
import {EmptyState} from '../../components/EmptyState'
import {FederatedCredentialGuidance} from '../../components/FederatedCredentialGuidance'

const MAX_SINKS = 2

export function Index() {
  const {sinks, createPath, basePath, testConnectionPath, subjectClaim, fetchError} =
    useRoutePayload<IndexRoutePayload>()
  const canAddMore = sinks.length < MAX_SINKS

  return (
    <div>
      <div className="d-flex flex-justify-between flex-items-center tmp-mb-3">
        <Heading as="h2" className="f3">
          Data streams
        </Heading>
      </div>

      {fetchError && (
        <Flash variant="danger" className="tmp-mb-3">
          Data streams could not be loaded. Please try again later.
        </Flash>
      )}

      {sinks.length === 0 && !fetchError ? (
        <EmptyState createPath={createPath} />
      ) : (
        <>
          {sinks.length > 0 && <SinkList sinks={sinks} basePath={basePath} testConnectionPath={testConnectionPath} />}
          {canAddMore && !fetchError && <EmptyState createPath={createPath} variant="secondary" />}
        </>
      )}

      <FederatedCredentialGuidance subjectClaim={subjectClaim} />
    </div>
  )
}
