import React, {useState, useCallback} from 'react'
import {ActionList, ActionMenu, Flash, IconButton, Label} from '@primer/react'
import {
  CheckCircleIcon,
  BlockedIcon,
  AlertIcon,
  KebabHorizontalIcon,
  PencilIcon,
  TrashIcon,
  PlayIcon,
  PauseIcon,
  BeakerIcon,
} from '@primer/octicons-react'
import {verifiedFetchJSON} from '@github-ui/verified-fetch'
import type {Sink, SinkStatus, TestConnectionResult} from '../types'
import {SINK_TYPE_LABELS, STATUS_LABELS} from '../types'
import {DeleteDialog} from './DeleteDialog'
import {PauseResumeDialog} from './PauseResumeDialog'

interface SinkListProps {
  sinks: Sink[]
  basePath: string
  testConnectionPath: string
}

const statusIcon: Record<SinkStatus, {icon: typeof CheckCircleIcon; color: string}> = {
  active: {icon: CheckCircleIcon, color: 'var(--fgColor-success)'},
  paused: {icon: PauseIcon, color: 'var(--fgColor-attention)'},
  disabled: {icon: BlockedIcon, color: 'var(--fgColor-muted)'},
  error: {icon: AlertIcon, color: 'var(--fgColor-danger)'},
}

export function SinkList({sinks, basePath, testConnectionPath}: SinkListProps) {
  return (
    <div className="d-flex flex-column gap-2">
      {sinks.map(sink => (
        <SinkRow key={sink.id} sink={sink} basePath={basePath} testConnectionPath={testConnectionPath} />
      ))}
    </div>
  )
}

// eslint-disable-next-line @typescript-eslint/no-shadow -- named function expression intentionally shares the outer name
const SinkRow = React.memo(function SinkRow({
  sink,
  basePath,
  testConnectionPath,
}: {
  sink: Sink
  basePath: string
  testConnectionPath: string
}) {
  const [deleteOpen, setDeleteOpen] = useState(false)
  const [pauseResumeOpen, setPauseResumeOpen] = useState(false)
  const [testResult, setTestResult] = useState<TestConnectionResult | null>(null)
  const [isTesting, setIsTesting] = useState(false)

  const StatusIcon = statusIcon[sink.status]?.icon ?? CheckCircleIcon
  const statusColor = statusIcon[sink.status]?.color ?? 'var(--fgColor-default)'
  const isPaused = sink.status === 'paused'

  const handleDelete = useCallback(() => setDeleteOpen(true), [])
  const handlePauseResume = useCallback(() => setPauseResumeOpen(true), [])

  const handleTestConnection = useCallback(async () => {
    if (isTesting) return
    setIsTesting(true)
    setTestResult(null)

    try {
      const response = await verifiedFetchJSON(testConnectionPath, {
        method: 'POST',
        body: {sink_id: sink.id},
      })
      const data = (await response.json()) as TestConnectionResult
      setTestResult(data)
    } catch {
      setTestResult({success: false, error_message: 'Something went wrong.', status_code: 0, latency_ms: 0})
    } finally {
      setIsTesting(false)
    }
  }, [isTesting, testConnectionPath, sink.id])

  return (
    <div className="border rounded-2 tmp-p-3">
      <div className="d-flex flex-justify-between flex-items-center">
        <div className="d-flex flex-items-center gap-2">
          <span style={{color: statusColor, display: 'flex'}}>
            <StatusIcon size={16} />
          </span>
          <div>
            <span className="text-bold">{sink.name}</span>
            <span className="color-fg-muted ml-2 f6">{SINK_TYPE_LABELS[sink.sinkType] ?? sink.sinkType}</span>
            {sink.status !== 'active' && (
              <Label
                className="ml-2"
                variant={sink.status === 'error' ? 'danger' : sink.status === 'paused' ? 'attention' : 'secondary'}
              >
                {STATUS_LABELS[sink.status]}
              </Label>
            )}
          </div>
        </div>

        <ActionMenu>
          <ActionMenu.Anchor>
            <IconButton icon={KebabHorizontalIcon} variant="invisible" aria-label={`Actions for ${sink.name}`} />
          </ActionMenu.Anchor>
          <ActionMenu.Overlay>
            <ActionList>
              <ActionList.LinkItem href={`${basePath}/${sink.id}/edit`}>
                <ActionList.LeadingVisual>
                  <PencilIcon />
                </ActionList.LeadingVisual>
                <span>Edit</span>
              </ActionList.LinkItem>
              <ActionList.Item onSelect={handleTestConnection} disabled={isTesting}>
                <ActionList.LeadingVisual>
                  <BeakerIcon />
                </ActionList.LeadingVisual>
                <span>{isTesting ? 'Testing…' : 'Test connection'}</span>
              </ActionList.Item>
              <ActionList.Item onSelect={handlePauseResume}>
                <ActionList.LeadingVisual>{isPaused ? <PlayIcon /> : <PauseIcon />}</ActionList.LeadingVisual>
                <span>{isPaused ? 'Resume stream' : 'Pause stream'}</span>
              </ActionList.Item>
              <ActionList.Divider />
              <ActionList.Item variant="danger" onSelect={handleDelete}>
                <ActionList.LeadingVisual>
                  <TrashIcon />
                </ActionList.LeadingVisual>
                <span>Delete</span>
              </ActionList.Item>
            </ActionList>
          </ActionMenu.Overlay>
        </ActionMenu>
      </div>

      {sink.healthStatus && sink.healthStatus !== 'healthy' && (
        <div className="tmp-mt-2 f6 border-top tmp-pt-2">
          <div className="d-flex flex-items-center gap-2 mb-1">
            <Label variant={sink.healthStatus === 'unhealthy' ? 'danger' : 'attention'}>
              {sink.healthStatus === 'unhealthy' ? 'Unhealthy' : 'Degraded'}
            </Label>
          </div>
          {sink.lastError && (
            <div className="d-flex flex-items-center gap-2 mb-1">
              <span className="color-fg-danger d-flex">
                <AlertIcon size={14} />
              </span>
              <span className="color-fg-default">{sink.lastError}</span>
            </div>
          )}
          <div className="d-flex gap-3 color-fg-muted">
            {sink.lastSuccessAt && <span>Last success: {new Date(sink.lastSuccessAt).toLocaleString()}</span>}
            {sink.lastFailureAt && <span>Last failure: {new Date(sink.lastFailureAt).toLocaleString()}</span>}
          </div>
        </div>
      )}

      {testResult && (
        <Flash variant={testResult.success ? 'success' : 'danger'} className="tmp-mt-2">
          {testResult.success ? (
            <span>Connection successful ({testResult.latency_ms}ms)</span>
          ) : (
            <span>
              <span>Connection failed</span>
              {testResult.error_message ? <span>: {testResult.error_message}</span> : null}
              {testResult.latency_ms > 0 && <span> ({testResult.latency_ms}ms)</span>}
            </span>
          )}
        </Flash>
      )}

      {deleteOpen && (
        <DeleteDialog sinkId={sink.id} sinkName={sink.name} basePath={basePath} onClose={() => setDeleteOpen(false)} />
      )}

      {pauseResumeOpen && (
        <PauseResumeDialog
          sinkId={sink.id}
          sinkName={sink.name}
          isPaused={isPaused}
          basePath={basePath}
          onClose={() => setPauseResumeOpen(false)}
        />
      )}
    </div>
  )
})
