export type SinkType = 'azure_kusto' | 'azure_blob' | 'azure_event_hub' | 's3' | 'aws_firehose'

export type SinkStatus = 'active' | 'paused' | 'disabled' | 'error'

export type HealthStatus = 'healthy' | 'degraded' | 'unhealthy'

export interface Sink {
  id: string
  name: string
  sinkType: SinkType
  status: SinkStatus
  config: Record<string, string>
  healthStatus?: HealthStatus
  lastError?: string
  lastSuccessAt?: string
  lastFailureAt?: string
}

// FieldDef describes a single user-facing config field for a sink type.
// `required` defaults to true. Optional fields ship as empty inputs whose
// `placeholder` shows the server-applied default so users can leave them
// blank. Fields with `options` render as a <Select> dropdown. `default`
// supplies the initial value for new sinks (used so a select can default
// to a non-first option while keeping its list in a useful order).
export interface FieldDef {
  key: string
  label: string
  placeholder?: string
  required?: boolean
  default?: string
  options?: Array<{value: string; label: string}>
}

