import {useState, useCallback} from 'react'
import {Dialog, Flash} from '@primer/react'
import {verifiedFetchJSON} from '@github-ui/verified-fetch'

interface PauseResumeDialogProps {
  sinkId: string
  sinkName: string
  isPaused: boolean
  basePath: string
  onClose: () => void
}

export function PauseResumeDialog({sinkId, sinkName, isPaused, basePath, onClose}: PauseResumeDialogProps) {
  const [isSubmitting, setIsSubmitting] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const action = isPaused ? 'resume' : 'pause'
  const actionLabel = isPaused ? 'Resume stream' : 'Pause stream'

  const handleSubmit = useCallback(async () => {
    if (isSubmitting) return

    setIsSubmitting(true)
    setError(null)

    try {
      const response = await verifiedFetchJSON(`${basePath}/${sinkId}/${action}`, {method: 'PUT'})

      if (response.ok) {
        window.location.href = basePath
      } else {
        const data = (await response.json()) as {errors?: string}
        setError(data?.errors ?? `Failed to ${action} stream.`)
        setIsSubmitting(false)
      }
    } catch {
      setError('Something went wrong. Please try again.')
      setIsSubmitting(false)
    }
  }, [basePath, sinkId, action, isSubmitting])

  return (
    <Dialog
      title={actionLabel}
      onClose={onClose}
      width="medium"
      footerButtons={[{buttonType: 'default', content: actionLabel, inactive: isSubmitting, onClick: handleSubmit}]}
      renderBody={() => (
        <Dialog.Body>
          <span>
            Are you sure you want to {action} the stream <strong>{sinkName}</strong>?
          </span>
          {!isPaused && <span> While paused, no data will be forwarded to this destination.</span>}
          {error && (
            <Flash variant="danger" className="mt-2">
              {error}
            </Flash>
          )}
        </Dialog.Body>
      )}
    />
  )
}
