import {useRoutePayload} from '@github-ui/react-core/use-route-payload'
import {Heading} from '@primer/react'
import type {EditRoutePayload} from './types'
import {SinkForm} from '../../components/SinkForm'

export function Edit() {
  const {sink, updatePath, indexPath, testConnectionPath} = useRoutePayload<EditRoutePayload>()

  return (
    <div>
      <Heading as="h2" className="f3 tmp-mb-3">
        Edit data stream
      </Heading>
      <SinkForm
        submitPath={updatePath}
        cancelPath={indexPath}
        testConnectionPath={testConnectionPath}
        method="PUT"
        existingSink={sink}
      />
    </div>
  )
}
