import {useState, useCallback, useMemo, type FormEvent} from 'react'
import {Button, FormControl, Select, TextInput, Flash, Heading} from '@primer/react'
import {verifiedFetchJSON} from '@github-ui/verified-fetch'
import type {SinkType, Sink, TestConnectionResult, FieldDef} from '../types'
import {SINK_TYPE_LABELS, SUPPORTED_SINK_TYPES, SINK_TYPE_REGISTRY} from '../types'
import {DestinationFields} from './SinkFormFields/DestinationFields'
import {TestConnectionButton} from './TestConnectionButton'

// Build the initial config for a sink type by populating any fields that
// declare a `default`. Used for new sinks so dropdowns (which always have
// some value selected) match the server-side default.
function defaultConfigFor(fields: FieldDef[]): Record<string, string> {
  const out: Record<string, string> = {}
  for (const field of fields) {
    if (field.default !== undefined) out[field.key] = field.default
  }
  return out
}

interface SinkFormProps {
  submitPath: string
  cancelPath: string
  testConnectionPath: string
  method: 'POST' | 'PUT'
  existingSink?: Sink
}

export function SinkForm({submitPath, cancelPath, testConnectionPath, method, existingSink}: SinkFormProps) {
  const [name, setName] = useState(existingSink?.name ?? '')
  const [sinkType, setSinkType] = useState<SinkType>(existingSink?.sinkType ?? 'azure_kusto')
  const [config, setConfig] = useState<Record<string, string>>(
    () =>
      existingSink?.config ?? defaultConfigFor(SINK_TYPE_REGISTRY[existingSink?.sinkType ?? 'azure_kusto'].userFields),
  )
  const [isSubmitting, setIsSubmitting] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [connectionTested, setConnectionTested] = useState(false)

  const isEditing = !!existingSink

  const [initialConfig] = useState<Record<string, string>>(() => existingSink?.config ?? {})

  const userFields = SINK_TYPE_REGISTRY[sinkType].userFields
  const staticConfig = SINK_TYPE_REGISTRY[sinkType].staticConfig

  const configChanged = useMemo(() => {
    if (!isEditing) return true
    return userFields.some(field => (config[field.key] ?? '') !== (initialConfig[field.key] ?? ''))
  }, [isEditing, config, initialConfig, userFields])

  const handleConfigChange = useCallback((key: string, value: string) => {
    setConfig(prev => ({...prev, [key]: value}))
    setConnectionTested(false)
  }, [])

  const isValid = useMemo(() => {
    if (!name.trim()) return false
    return userFields.every(field => {
      if (field.required === false) return true
      return (config[field.key] ?? '').trim().length > 0
    })
  }, [name, config, userFields])

  const needsTest = !isEditing || configChanged
  const canSubmit = isValid && (!needsTest || connectionTested)

  const handleTestResult = useCallback((result: TestConnectionResult) => {
    setConnectionTested(result.success)
  }, [])

  const handleSubmit = useCallback(
    async (e: FormEvent) => {
      e.preventDefault()
      if (isSubmitting || !canSubmit) return

      setIsSubmitting(true)
      setError(null)

      const mergedConfig = {...config, ...staticConfig}

      const body: Record<string, unknown> = {
        name,
        config: mergedConfig,
      }

      if (!isEditing) {
        body.sink_type = sinkType
      }

      try {
        const response = await verifiedFetchJSON(submitPath, {method, body})

        if (response.ok) {
          const data = (await response.json()) as {payload: {redirect_url: string}}
          window.location.href = data.payload.redirect_url
        } else {
          const data = (await response.json()) as {errors?: string}
          setError(data?.errors ?? 'Something went wrong. Please try again.')
          setIsSubmitting(false)
        }
      } catch {
        setError('Something went wrong. Please try again.')
        setIsSubmitting(false)
      }
    },
    [isSubmitting, canSubmit, sinkType, config, staticConfig, name, isEditing, submitPath, method],
  )

  return (
    <form onSubmit={handleSubmit} className="col-md-8">
      {error && (
        <Flash variant="danger" className="tmp-mb-3">
          {error}
        </Flash>
      )}

      <div className="tmp-mb-3">
        <FormControl required>
          <FormControl.Label>Stream name</FormControl.Label>
          <TextInput value={name} onChange={e => setName(e.target.value)} placeholder="My data stream" block />
        </FormControl>
      </div>

      <div className="tmp-mb-3">
        <FormControl required disabled={isEditing} id="sink-destination-type">
          <FormControl.Label>Destination type</FormControl.Label>
          {isEditing ? (
            <TextInput value={SINK_TYPE_LABELS[sinkType] ?? sinkType} block />
          ) : (
            <Select
              value={sinkType}
              onChange={e => {
                const next = e.target.value as SinkType
                setSinkType(next)
                setConfig(defaultConfigFor(SINK_TYPE_REGISTRY[next].userFields))
                setConnectionTested(false)
              }}
            >
              {SUPPORTED_SINK_TYPES.map(type => (
                <Select.Option key={type} value={type}>
                  {SINK_TYPE_LABELS[type]}
                </Select.Option>
              ))}
            </Select>
          )}
        </FormControl>
      </div>

      <Heading as="h3" className="f4 tmp-mb-3">
        Configuration
      </Heading>

      <div className="d-flex flex-column gap-3 tmp-mb-3">
        <DestinationFields sinkType={sinkType} config={config} onChange={handleConfigChange} disabled={isSubmitting} />
      </div>

      <div className="tmp-mb-3">
        <TestConnectionButton
          testConnectionPath={testConnectionPath}
          sinkId={existingSink?.id}
          sinkType={!existingSink ? sinkType : undefined}
          config={!existingSink ? {...config, ...staticConfig} : undefined}
          name={!existingSink ? name : undefined}
          disabled={!existingSink && !isValid}
          onTestResult={handleTestResult}
        />
      </div>

      <div className="d-flex gap-2">
        <Button type="submit" variant="primary" disabled={!canSubmit || isSubmitting}>
          {isSubmitting ? 'Saving...' : isEditing ? 'Update stream' : 'Create stream'}
        </Button>
        <Button as="a" href={cancelPath}>
          Cancel
        </Button>
      </div>
    </form>
  )
}
