import {Button, Heading} from '@primer/react'
import {PlusIcon} from '@primer/octicons-react'

interface EmptyStateProps {
  createPath: string
  variant?: 'primary' | 'secondary'
}

export function EmptyState({createPath, variant = 'primary'}: EmptyStateProps) {
  const isPrimary = variant === 'primary'

  return (
    <div className={`text-center border rounded-2 tmp-py-6 tmp-px-3${isPrimary ? '' : ' tmp-mt-3'}`}>
      <Heading as="h3" className="f4 mb-2">
        {isPrimary ? 'No data streams configured' : 'Add a backup stream'}
      </Heading>
      <p className="color-fg-muted tmp-mb-3">
        {isPrimary
          ? 'Data streams let you forward Actions telemetry to an external destination for analysis and monitoring.'
          : 'Configure a secondary stream as a backup to ensure data is always delivered, even if your primary destination is unavailable.'}
      </p>
      <Button as="a" href={createPath} variant="primary" leadingVisual={PlusIcon}>
        New stream
      </Button>
    </div>
  )
}
