import type {SinkType} from '../../types'
import {SINK_TYPE_REGISTRY} from '../../types'
import {FieldList} from './FieldList'

interface DestinationFieldsProps {
  sinkType: SinkType
  config: Record<string, string>
  onChange: (key: string, value: string) => void
  disabled?: boolean
}

export function DestinationFields({sinkType, config, onChange, disabled}: DestinationFieldsProps) {
  const entry = SINK_TYPE_REGISTRY[sinkType]
  if (!entry) return null

  return <FieldList fields={entry.userFields} config={config} onChange={onChange} disabled={disabled} />
}
