import {useState, useCallback} from 'react'
import {Dialog, Flash} from '@primer/react'
import {verifiedFetchJSON} from '@github-ui/verified-fetch'

interface DeleteDialogProps {
  sinkId: string
  sinkName: string
  basePath: string
  onClose: () => void
}

export function DeleteDialog({sinkId, sinkName, basePath, onClose}: DeleteDialogProps) {
  const [isSubmitting, setIsSubmitting] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const handleDelete = useCallback(async () => {
    if (isSubmitting) return

    setIsSubmitting(true)
    setError(null)

    try {
      const response = await verifiedFetchJSON(`${basePath}/${sinkId}`, {method: 'DELETE'})

      if (response.ok) {
        window.location.href = basePath
      } else {
        const data = (await response.json()) as {errors?: string}
        setError(data?.errors ?? 'Failed to delete stream.')
        setIsSubmitting(false)
      }
    } catch {
      setError('Something went wrong. Please try again.')
      setIsSubmitting(false)
    }
  }, [basePath, sinkId, isSubmitting])

  return (
    <Dialog
      title="Delete data stream"
      onClose={onClose}
      width="medium"
      footerButtons={[{buttonType: 'danger', content: 'Delete stream', inactive: isSubmitting, onClick: handleDelete}]}
      renderBody={() => (
        <Dialog.Body>
          <span>
            Are you sure you want to delete the stream <strong>{sinkName}</strong>? This action cannot be undone.
          </span>
          {error && (
            <Flash variant="danger" className="mt-2">
              {error}
            </Flash>
          )}
        </Dialog.Body>
      )}
    />
  )
}
